import { TipoMenu } from "@/types/menu";

interface TabsCategoriasProps {
  categoriaActiva: TipoMenu;
  onChangeCategoria: (cat: TipoMenu) => void;
}

const categorias: { label: string; value: TipoMenu }[] = [
  { label: "🍽️ Platillos", value: TipoMenu.Platos },
  { label: "🍰 Postres", value: TipoMenu.Postre },
  { label: "🥤 Bebidas", value: TipoMenu.Bebidas },
];

export default function TabsCategorias({
  categoriaActiva,
  onChangeCategoria,
}: TabsCategoriasProps) {
  return (
    <div className="flex border-b border-gray-200">
      {categorias.map((cat) => (
        <button
          key={cat.value}
          onClick={() => onChangeCategoria(cat.value)}
          className={`px-5 py-3 text-sm font-medium transition-colors relative ${
            categoriaActiva === cat.value
              ? "text-blue-600"
              : "text-gray-500 hover:text-gray-700"
          }`}
        >
          {cat.label}
          {categoriaActiva === cat.value && (
            <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600 rounded-t" />
          )}
        </button>
      ))}
    </div>
  );
}
