"use client";

import { useState } from "react";
import Modal from "@/components/ui/modal";
import Button from "@/components/ui/button";
import { Menu } from "@/types/menu";

interface ModalProductoProps {
  producto: Menu | null;
  isOpen: boolean;
  onClose: () => void;
  onAgregar: (producto: Menu, cantidad: number) => void;
}

export default function ModalProducto({
  producto,
  isOpen,
  onClose,
  onAgregar,
}: ModalProductoProps) {
  const [cantidad, setCantidad] = useState(1);

  const handleClose = () => {
    setCantidad(1);
    onClose();
  };

  const handleAgregar = () => {
    if (producto) {
      onAgregar(producto, cantidad);
      setCantidad(1);
      onClose();
    }
  };

  if (!producto) return null;

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title={producto.nombre}>
      <div className="space-y-4">
        {/* Imagen */}
        <div className="h-40 bg-gray-100 rounded-lg flex items-center justify-center text-5xl">
          {producto.imagen ? (
            <img
              src={producto.imagen}
              alt={producto.nombre}
              className="w-full h-full object-cover rounded-lg"
            />
          ) : (
            "🍴"
          )}
        </div>

        {/* Descripción */}
        <p className="text-sm text-gray-500">{producto.descripcion}</p>

        {/* Precio */}
        <p className="text-lg font-bold text-blue-600">
          S/ {producto.precio.toFixed(2)}
        </p>

        {/* Cantidad */}
        <div className="flex items-center justify-center gap-4">
          <button
            onClick={() => setCantidad((prev) => Math.max(1, prev - 1))}
            className="w-10 h-10 rounded-full bg-gray-100 hover:bg-gray-200 text-xl font-bold text-gray-600 transition-colors flex items-center justify-center"
          >
            −
          </button>
          <span className="text-xl font-bold text-gray-800 w-8 text-center">
            {cantidad}
          </span>
          <button
            onClick={() => setCantidad((prev) => prev + 1)}
            className="w-10 h-10 rounded-full bg-gray-100 hover:bg-gray-200 text-xl font-bold text-gray-600 transition-colors flex items-center justify-center"
          >
            +
          </button>
        </div>

        {/* Botón agregar */}
        <Button variant="primary" className="w-full" onClick={handleAgregar}>
          Agregar — S/ {(producto.precio * cantidad).toFixed(2)}
        </Button>
      </div>
    </Modal>
  );
}
