import Button from "@/components/ui/button";

export interface ItemComanda {
  idMenu: number;
  nombre: string;
  cantidad: number;
  precioUnitario: number;
}

interface FooterComandaProps {
  items: ItemComanda[];
  onVerComanda: () => void;
}

export default function FooterComanda({
  items,
  onVerComanda,
}: FooterComandaProps) {
  if (items.length === 0) return null;

  const totalItems = items.reduce((acc, item) => acc + item.cantidad, 0);
  const totalProductos = items.length;

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-[0_-4px_12px_rgba(0,0,0,0.08)] z-40 animate-slide-up">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3 flex items-center justify-between">
        {/* Resumen de items */}
        <div className="flex items-center gap-3 min-w-0">
          <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2.5 py-1 rounded-full shrink-0">
            {totalItems}
          </span>
          <span className="text-sm text-gray-700">
            {totalProductos} {totalProductos === 1 ? "producto" : "productos"} agregados
          </span>
        </div>

        {/* Botón comanda */}
        <Button variant="primary" onClick={onVerComanda} className="shrink-0">
          🧾 Ver Comanda
        </Button>
      </div>
    </div>
  );
}
