import { Menu } from "@/types/menu";

interface ProductoCardProps {
  producto: Menu;
  onClick: (producto: Menu) => void;
}

export default function ProductoCard({ producto, onClick }: ProductoCardProps) {
  return (
    <button
      onClick={() => onClick(producto)}
      className="bg-white rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-all text-left overflow-hidden"
    >
      {/* Imagen */}
      <div className="h-36 bg-gray-100 flex items-center justify-center text-4xl">
        {producto.imagen ? (
          <img
            src={producto.imagen}
            alt={producto.nombre}
            className="w-full h-full object-cover"
          />
        ) : (
          "🍴"
        )}
      </div>

      {/* Info */}
      <div className="p-3 space-y-1">
        <p className="font-semibold text-gray-800 truncate">{producto.nombre}</p>
        <p className="text-xs text-gray-400 truncate">{producto.descripcion}</p>
        <p className="text-sm font-bold text-blue-600">S/ {producto.precio.toFixed(2)}</p>
      </div>
    </button>
  );
}
