"use client";

import { useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { Menu, TipoMenu } from "@/types/menu";
import HeaderMesero from "../../../components/header-mesero";
import TabsCategorias from "./components/tabs-categorias";
import GridProductos from "./components/grid-productos";
import ModalProducto from "./components/modal-producto";
import FooterComanda, { ItemComanda } from "./components/footer-comanda";

// ---------- MOCK DATA ----------
const productosMock: Menu[] = [
  { idMenu: 1, nombre: "Lomo Saltado", descripcion: "Carne salteada con cebolla, tomate y papas fritas", precio: 28.0, tipo: TipoMenu.Platos, categoria: "Platos", imagen: "", estado: true },
  { idMenu: 2, nombre: "Ají de Gallina", descripcion: "Crema de ají amarillo con pollo deshilachado", precio: 24.0, tipo: TipoMenu.Platos, categoria: "Platos", imagen: "", estado: true },
  { idMenu: 3, nombre: "Ceviche Clásico", descripcion: "Pescado fresco marinado en limón con cebolla y ají", precio: 32.0, tipo: TipoMenu.Platos, categoria: "Platos", imagen: "", estado: true },
  { idMenu: 4, nombre: "Arroz con Pollo", descripcion: "Arroz verde con piezas de pollo y ensalada", precio: 22.0, tipo: TipoMenu.Platos, categoria: "Platos", imagen: "", estado: true },
  { idMenu: 5, nombre: "Tres Leches", descripcion: "Bizcocho bañado en tres tipos de leche", precio: 14.0, tipo: TipoMenu.Postre, categoria: "Postres", imagen: "", estado: true },
  { idMenu: 6, nombre: "Suspiro Limeño", descripcion: "Manjar blanco con merengue de oporto", precio: 12.0, tipo: TipoMenu.Postre, categoria: "Postres", imagen: "", estado: true },
  { idMenu: 7, nombre: "Picarones", descripcion: "Aros de camote y zapallo con miel de chancaca", precio: 10.0, tipo: TipoMenu.Postre, categoria: "Postres", imagen: "", estado: true },
  { idMenu: 8, nombre: "Chicha Morada", descripcion: "Bebida de maíz morado con frutas y especias", precio: 8.0, tipo: TipoMenu.Bebidas, categoria: "Bebidas", imagen: "", estado: true },
  { idMenu: 9, nombre: "Pisco Sour", descripcion: "Cóctel clásico peruano con pisco y limón", precio: 18.0, tipo: TipoMenu.Bebidas, categoria: "Bebidas", imagen: "", estado: true },
  { idMenu: 10, nombre: "Limonada", descripcion: "Limonada natural con hierbabuena", precio: 7.0, tipo: TipoMenu.Bebidas, categoria: "Bebidas", imagen: "", estado: true },
];

export default function MenuPage() {
  const params = useParams();
  const router = useRouter();
  const mesaId = params.mesaId as string;

  const [categoriaActiva, setCategoriaActiva] = useState<TipoMenu>(TipoMenu.Platos);
  const [productoSeleccionado, setProductoSeleccionado] = useState<Menu | null>(null);
  const [modalAbierto, setModalAbierto] = useState(false);
  const [itemsComanda, setItemsComanda] = useState<ItemComanda[]>([]);

  const productosFiltrados = productosMock.filter(
    (p) => p.tipo === categoriaActiva && p.estado
  );

  const handleClickProducto = (producto: Menu) => {
    setProductoSeleccionado(producto);
    setModalAbierto(true);
  };

  const handleAgregar = (producto: Menu, cantidad: number) => {
    setItemsComanda((prev) => {
      const existente = prev.find((item) => item.idMenu === producto.idMenu);
      if (existente) {
        return prev.map((item) =>
          item.idMenu === producto.idMenu
            ? { ...item, cantidad: item.cantidad + cantidad }
            : item
        );
      }
      return [
        ...prev,
        {
          idMenu: producto.idMenu,
          nombre: producto.nombre,
          cantidad,
          precioUnitario: producto.precio,
        },
      ];
    });
  };

  const handleVerComanda = () => {
    // Placeholder: navegar a resumen de comanda
    alert(
      `Comanda Mesa ${mesaId}:\n${itemsComanda
        .map((i) => `${i.cantidad}x ${i.nombre}`)
        .join("\n")}`
    );
  };

  const handleVolver = () => {
    router.push("/mesero/mesas");
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      <HeaderMesero seccion={`Mesa ${mesaId}`} />

      {/* Botón volver */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-4">
        <button
          onClick={handleVolver}
          className="flex items-center gap-1 text-sm text-gray-500 hover:text-gray-700 transition-colors"
        >
          ← Volver a mesas
        </button>
      </div>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Tabs de categoría */}
        <TabsCategorias
          categoriaActiva={categoriaActiva}
          onChangeCategoria={setCategoriaActiva}
        />

        {/* Grid de productos */}
        <GridProductos
          productos={productosFiltrados}
          onClickProducto={handleClickProducto}
        />
      </main>

      {/* Modal producto */}
      <ModalProducto
        producto={productoSeleccionado}
        isOpen={modalAbierto}
        onClose={() => setModalAbierto(false)}
        onAgregar={handleAgregar}
      />

      {/* Footer comanda */}
      <FooterComanda items={itemsComanda} onVerComanda={handleVerComanda} />
    </div>
  );
}
